import React, {useEffect,useRef, useState} from 'react'
import styled from "styled-components"
import {useSelector, useDispatch} from "react-redux"
import Channel from "./Channel"
import {setPlayingChannel} from "../../actions/playingChannel"
import { FixedSizeList as List } from "react-window";
import {convertRemToPixels,convertVhToPixels} from "../../other/convert-rem"
import {useHistory,useLocation} from "react-router-dom";
import Popup from "../Popup/Popup"

const ChannelsList = styled.ul`
height: calc(95vh - 3rem);
padding: .8rem .6rem;
background-color: var(--first-color);
list-style-type: none;
border-left: 1px solid #000;
transform: translateY(-1px);
box-shadow: 0 7px 14px rgb(50 50 93 / 10%), 0 3px 6px rgb(0 0 0 / 8%);
&:focus{
    outline-width: 0px;
}
`

const Channels = ({playlist}) => {
    const playingChannel = useSelector(state => state.playingCh);
    let channelIndex = 0
    
    const query = useQuery();
    const searchText = query.get("search");
    
    const [showPopup, setShowPopup] = useState(false);
    const [channelsPlaylist, setChannelsPlaylist] = useState(playlist);


    const dispatch = useDispatch()
    const history = useHistory();
    const location = useLocation();
    const listRef = useRef();

    
    useEffect(() => {
      if(playingChannel){
        setTimeout(()=>focusChannel(),100)
      }
    }, [playingChannel]);

    useEffect(() => {
      setChannelsPlaylist(playlist)
      setTimeout(()=>focusChannel(),100)
    }, [playlist]);


    useEffect(() => {
      const searched = searchText ? playlist.filter(x=> x.name.toLowerCase().includes(searchText.toLowerCase())) : playlist
      if(searched.length>0){
        setChannelsPlaylist(searched)
        setTimeout(() => focusChannel(), 100);
      }else if(searchText)
        setShowPopup(1)
      else history.push("/live/category/")
    }, [searchText]);

    useEffect(() => {
      // if (location === '/live/category/') {
      //   console.log('【不响应】');
      // } else {
        document.onkeydown = function (event) {
          console.log('【路由-换自己监听】', location);
          if (location.pathname === '/live/category/') {
            console.log('【不响应】');
          } else {
            let e = event || window.event || arguments.callee.caller.arguments[0];
            console.log('【按键】', e.keyCode);
            e.preventDefault();
            console.log('【监听按钮-阻止默认事件】', event.key);
            switch (e.keyCode) {
                case 38: // 上
                    console.log('【上】');
                    switchDomUp()
                    break;
                case 40: // 下
                    console.log('【下】');
                    switchDomDown()
                    break;
                case 37: // 左
                    console.log('【左】');
                    break;
                case 39: // 右
                    console.log('【右】');
                    break;
                case 13: // 确认
                    console.log('【确定】');
                    break;
                case '4': // 返回
                    console.log('【返回】');
                    break;
            
                default:
                    break;
            }
          }
          
        };
        // window.controlKey = function (data) {
        //   console.log('【键值传递监听-频道列表live-测试2222】', data);
        //   data = Number(data)
        //   switch (data) {
        //     case 19: // 上
        //         console.log('【上】');
        //         switchDomUp()
        //         break;
        //     case 20: // 下
        //         console.log('【下】');
        //         switchDomDown()
        //         break;
        //     case 21: // 左
        //         console.log('【左】');
        //         break;
        //     case 22: // 右
        //         console.log('【右】');
        //         break;
        //     case 23: // 确认
        //         console.log('【确定】');
        //         break;
        //     case 4: // 返回
        //         console.log('【返回】');
        //         break;
        
        //     default:
        //         break;
        //   }
        // }
      // }
    }, [location])

    const focusChannel = () => {
      channelIndex = localStorage.getItem('channelIndex') || 0
      console.log("【localStorage.getItem('channelIndex')】",localStorage.getItem('channelIndex'));
      if(document.getElementById("selectedCh")){
        console.log('【已选择-selectedCh】');
        // document.getElementById("selectedCh").focus()
        document.getElementById("selectedCh").classList.toggle('channel-list-active')
      }else{
        console.log('【未选择】');
        // document.querySelector(".channel").focus()
        console.log("【document.getElementsByClassName('channel-list-id')】", document.getElementsByClassName('channel-list-id'));
        document.getElementsByClassName('channel-list-id')[channelIndex].classList.toggle('channel-list-active')
        dispatch(setPlayingChannel(channelsPlaylist[channelIndex]))
      }
    }

    const switchDomUp = () => {
      const channelElement = document.getElementsByClassName('channel-list-id')
      console.log('【channelElement-上】', channelElement);
      console.log('【channelIndex-上】', channelIndex);
      if (channelIndex > 0) {
        channelElement[channelIndex].classList.toggle('channel-list-active')
        channelIndex--
        channelElement[channelIndex].classList.toggle('channel-list-active')
        localStorage.setItem('channelIndex', channelIndex)
        setTimeout(()=>{
          dispatch(setPlayingChannel(channelsPlaylist[channelIndex]))
        },1000)
      } else {
        channelElement[channelIndex].classList.toggle('channel-list-active')
        setTimeout(()=>{
          dispatch(setPlayingChannel(channelsPlaylist[channelIndex]))
        },1000)
      }
    }

    const switchDomDown = () => {
      const channelElement = document.getElementsByClassName('channel-list-id')
      console.log('【channelElement-下】', channelElement);
      console.log('【channelIndex-下】', channelIndex);
      if (channelIndex < channelElement.length) {
        channelElement[channelIndex].classList.toggle('channel-list-active')
        channelIndex++
        channelElement[channelIndex].classList.toggle('channel-list-active')
        localStorage.setItem('channelIndex', channelIndex)
        setTimeout(()=>{
          dispatch(setPlayingChannel(channelsPlaylist[channelIndex]))
        },1000)
      } else {
        channelElement[channelIndex].classList.toggle('channel-list-active')
        setTimeout(()=>{
          dispatch(setPlayingChannel(channelsPlaylist[channelIndex]))
        },1000)
      }
    }

    console.log('【频道列表】', channelsPlaylist);


    const Row = ({ index, style }) => (
        <Channel key={channelsPlaylist[index].stream_id} 
          Name={channelsPlaylist[index].name} 
          Shift = {channelsPlaylist[index].shift} 
          Epg={channelsPlaylist[index].epg_channel_id} 
          id={channelsPlaylist[index].stream_id} Image={channelsPlaylist[index].stream_icon} 
          Number={channelsPlaylist[index].num} 
          selectEvent={() => {
            dispatch(setPlayingChannel(channelsPlaylist[index]))
          }}
          virtualScrollStyle={style} 
          selected={playingChannel && playingChannel.stream_id === channelsPlaylist[index].stream_id}
          index={index} />
    );

    return (
      <>
        <ChannelsList>
            <List
              height={convertVhToPixels("95vh")-convertRemToPixels(5)}
              itemCount={channelsPlaylist.length}
              itemSize={convertRemToPixels(5)}
              style={{overflowY:"auto", maxHeight: "calc(95vh - 3rem)"}}
              useIsScrolling={true}
              ref={listRef}
            >
              {Row}
            </List>          
        </ChannelsList>
        {showPopup && <Popup title={`No stream found with '${searchText}'`} description={"Search will be resetted."} icon={"fas fa-search"}  onclick={()=>{
          setShowPopup(0);
          focusChannel();
          history.replace(location.pathname.split("?")[0])
        }}/>}
      </>
    )
}

const useQuery = () => {
  return new URLSearchParams(useLocation().search);
}

export default Channels
