import React, {useState, useEffect} from "react"
import "./Groups.css"
import styled from "styled-components"
import {useSelector} from "react-redux"
import {useHistory, useParams, useLocation} from "react-router-dom";
import {getGroup} from "../../other/last-opened-mode"



const Input = styled.input`
&:focus{
    border-color: var(--second-color);
    box-shadow: 0 0 0 0.2rem var(--second-color-shadow);
    transition: all .5s ease;
}`


const Groups = () => {
    let liIndex = 0
    let groupsKeyCode = 0
    const [navbar,setNavbar] = useState(false)
    const [searchValue, setSearchValue] = useState("");

    const history = useHistory();
    const { playingMode, category } = useParams();
    
    const groupsTemp = useSelector(state => state.groupsList);
    const [groups, setGroups] = useState(groupsTemp)

    const location = useLocation();

    const closeBar = () => {
        setNavbar(false)
        setTimeout(()=> history.goBack(),500);
    }

    useEffect(()=>{
        setNavbar(isNaN(category))
        console.log('【渲染之后1】');
    },[category])

    const searchGroup = (text) =>{
        setSearchValue(text);
        setGroups(text ? groupsTemp.filter(x=> x.category_name.toLowerCase().includes(text.toLowerCase())) : groupsTemp)
    }

    useEffect(()=>{
        setSearchValue()
        setGroups(groups)
    },[groupsTemp])

    const selectGroup = (gp) =>{
        console.log('【点击菜单】', gp, liIndex);
        localStorage.setItem('channelIndex', 0)
        setNavbar(false);
        if(gp===-1 && playingMode !== "live")
            setTimeout(()=>history.replace(`/${playingMode}/`), 500);
        else{
            setGroups(groups[gp].category_id)
            setTimeout(()=>history.replace(`/${playingMode}/category/${groups[gp].category_id}/`), 500);
        }
    }


    useEffect(() => {
        console.log('【渲染之后2】');
        setTimeout(()=>{
            if (document.getElementsByClassName('liveList')[0]) {
                document.getElementsByClassName('liveList')[0].classList.toggle('li-active')
            }
		},100)
        if(!groups || groups.length===0)
        console.log('【跳转到首页】');
            history.replace("/")
    }, []);

    useEffect(() => {
        document.onkeydown = function (event) {
            console.log('【路由-换自己监听-groups】', location);
            if (location.pathname === '/live/category/') {
                let e = event || window.event || arguments.callee.caller.arguments[0];
                console.log('【按键】', e.keyCode);
                groupsKeyCode = Number(e.keyCode)
                e.preventDefault();
                switchCode()
                // window.controlKey = function (data) {
                //     console.log('【键值传递监听-类型列表live】', data);
                //     console.log('【路由】', location);
                //     groupsKeyCode = Number(data)
                //     switchCode()
                // }
            } else {
                return
            }
            
        }
        
    }, [location])

    const moveFocus = (event) => {
		console.log('【moveFocus】', event.keyCode);
        event.preventDefault();
        console.log('远程控制键被阻止:', event.key);
        groupsKeyCode = Number(event.keyCode)
        console.log('【键盘keycode】', groupsKeyCode);
        switchCode()
        if (Number(event.keyCode) === 23 || Number(event.keyCode) === 13) {
            console.log("【document.getElementsByClassName('liveList')】", document.getElementsByClassName('liveList')[liIndex]);
            console.log("【document.getElementsByClassName('liveList')】", document.getElementsByClassName('liveList')[liIndex].val());
        }
        // remoteController(event);
    }

    const searchDoc = document.getElementById('searchInput')

    const qieListU = () => {
        console.log('【liIndex-前进】', liIndex);
        const abc = document.getElementsByClassName('liveList')
        const chang = abc.length
        if (liIndex < chang) {
            if (liIndex > -1) {
                abc[liIndex].classList.toggle('li-active')
                liIndex++
                abc[liIndex].classList.toggle('li-active')
            } else {
                liIndex = 0
                abc[liIndex].classList.toggle('li-active')
                searchDoc.blur()
            }
        } else {
            abc[liIndex].classList.toggle('li-active')
            searchDoc.blur()
        }
        console.log('【获取对象】', abc.length);
    }

    const qieListD = () => {
        console.log('【liIndex-后退】', liIndex);
        const abc = document.getElementsByClassName('liveList')
        if (liIndex > 0) {
            abc[liIndex].classList.toggle('li-active')
            liIndex--
            abc[liIndex].classList.toggle('li-active')
        } else {
            if (liIndex === 0) {
                abc[liIndex].classList.toggle('li-active')
                liIndex--
                searchDoc.focus()
                searchDoc.select()
            } else {
                console.log('【搜索框-到头】', searchDoc);
                searchDoc.focus()
                searchDoc.select()
            }
        }
        console.log('【获取对象】', abc.length);
    }

    const switchCode = () => {
        console.log('【判断】', groupsKeyCode);
        switch (groupsKeyCode) {
            case 19: // 上
                qieListD()
                break;
            case 20: // 下
                qieListU()
                break;
            case 21: // 左
                console.log('【左】');
                // if (liIndex < 0) {
                //     document.getElementsByClassName('netflix-close-btn-reverse')[0].focus()
                // }
                break;
            case 22: // 右
                console.log('【右】');
                break;
            case 23: // 确认
                console.log('【确定】');
                if (liIndex >= 0) {
                    selectGroup(liIndex)
                }
                break;
            case 4: // 返回
                console.log('【返回】');
                break;
            case 38: // 上
                qieListD()
                break;
            case 40: // 下
                qieListU()
                break;
        
            default:
                break;
        }
    }

    console.log('【页面加载】', groups);

    return (
        <>
        <div className={`netflix-nav-rev netflix-nav-rev-black ${navbar ? "visible" : ""}`}>
        	<div className={`netflix-nav-rev netflix-nav-rev-red ${navbar ? "visible" : ""}`}>
        		<div className={`netflix-nav-rev netflix-nav-rev-white ${navbar ? "visible" : ""}`}>
                    <div className="row">
                        <div className="col-7">
                            < Input className = "form-control"
                                type = "text"
                                id="searchInput"
                                spellCheck = {false}
                                placeholder = "Search category..."
                                onChange = {(e) => searchGroup(e.target.value)}
                                value = {searchValue}
                            />
                        </div>
                        <div className="col-auto">
                            <button className="netflix-nav-rev-btn netflix-close-btn netflix-close-btn-reverse" onClick={closeBar}><i className="fas fa-times"></i></button>
                        </div>
                    </div>
                   

        			<ul className="netflix-list netflix-list-reverse">
                    {/* {playingMode !== "live" && (
                        <li key={"GP-1"}>
                            <button
                                href = "#"
                                id={"*"} 
                                className = "lateral-focus group"
                                onClick={()=> selectGroup(-1)}
                                >
                                    All
                            </button>
                        </li>
                    )} */}
                    {groups && Array.isArray(groups) &&  (groups.map((gp,id) => (
                        <li key={"GP"+gp.category_id} className="liveList">
                            <button
                                href = "#"
                                id={gp.category_id===getGroup() ? "selectedGp" : ""} 
                                className = "lateral-focus group"
                                onClick={()=> selectGroup(id)}
                                >
                                    {gp.category_name}
                            </button>
                        </li>
                    )))}
        			</ul>
        		</div>
        	</div>
        </div>
        </>
    )
}

export default Groups
